#include <Arduino.h>
#include <Servo.h>
const int SHCP_PIN = A2;  
const int STCP_PIN = A1;  
const int DS_PIN = A0;    
const int BUTTON1_PIN = 2;  
const int BUTTON2_PIN = 3;  
const int BUTTON3_PIN = 4;  
const int SERVO1_PIN = 5;   
const int SERVO2_PIN = 6;   
Servo servo1;
Servo servo2;
const byte segmentCodes[] = {
  0b11000000, 
  0b11111001, 
  0b10100100, 
  0b10110000, 
  0b10011001, 
  0b10010010, 
  0b10000010, 
  0b11111000, 
  0b10000000, 
  0b10010000  
};
int currentNumber = 0;

void setup();
void loop();
void updateDisplayAndServos();
void displayNumber(int number);
void updateServos(int number);
void setup() {
  pinMode(SHCP_PIN, OUTPUT);
  pinMode(STCP_PIN, OUTPUT);
  pinMode(DS_PIN, OUTPUT);
  pinMode(BUTTON1_PIN, INPUT_PULLUP);
  pinMode(BUTTON2_PIN, INPUT_PULLUP);
  pinMode(BUTTON3_PIN, INPUT_PULLUP);
  servo1.attach(SERVO1_PIN);
  servo2.attach(SERVO2_PIN);
  displayNumber(currentNumber);
  updateServos(currentNumber);
}
void loop() {
  if (digitalRead(BUTTON1_PIN) == LOW) {
    delay(150); 
    if (digitalRead(BUTTON1_PIN) == LOW) {
      currentNumber += 1;
      if (currentNumber > 9) currentNumber = 0;
      updateDisplayAndServos();
      while (digitalRead(BUTTON1_PIN) == LOW); 
    }
  }
  if (digitalRead(BUTTON2_PIN) == LOW) {
    delay(150); 
    if (digitalRead(BUTTON2_PIN) == LOW) {
      currentNumber += 2;
      if (currentNumber > 9) currentNumber = 0;
      updateDisplayAndServos();
      while (digitalRead(BUTTON2_PIN) == LOW); 
    }
  }
  if (digitalRead(BUTTON3_PIN) == LOW) {
    delay(150); 
    if (digitalRead(BUTTON3_PIN) == LOW) {
      currentNumber += 3;
      if (currentNumber > 9) currentNumber = 0;
      updateDisplayAndServos();
      while (digitalRead(BUTTON3_PIN) == LOW); 
    }
  }
}
void updateDisplayAndServos() {
  displayNumber(currentNumber);
  updateServos(currentNumber);
}
void displayNumber(int number) {
  byte code = segmentCodes[number];
  shiftOut(DS_PIN, SHCP_PIN, MSBFIRST, code);
  digitalWrite(STCP_PIN, HIGH);
  digitalWrite(STCP_PIN, LOW);
}
void updateServos(int number) {
  if (number >= 0 && number <= 4) {
    servo1.write(0);
    servo2.write(90);
  } else if (number >= 5 && number <= 9) {
    servo1.write(90);
    servo2.write(180);
  }
}
